+@page "/chat"
+@namespace sv_7d707feea39f402d9d47253720ad38b8.Components.Pages.Chat
+@rendermode InteractiveServer
+@inject Services.IChatService ChatService
+
+<PageTitle>Chat</PageTitle>
+
+<div class="chat-layout @(threadOpen ? "thread-open" : "")">
+    <ChannelSidebar Channels="channels"
+                    SelectedChannelId="selectedChannelId"
+                    OnChannelSelected="SelectChannel" />
+
+    <MessageArea ChannelName="@currentChannelName"
+                 ChannelDescription="@currentChannelDescription"
+                 Messages="messages"
+                 ThreadSummaries="threadSummaries"
+                 IsLoadingMore="isLoadingMore"
+                 OnOpenThread="OpenThread"
+                 OnReact="HandleReaction"
+                 OnSendMessage="SendMessage"
+                 OnLoadMore="LoadMoreMessages" />
+
+    @if (threadOpen)
+    {
+        <ThreadPanel RootMessage="threadRootMessage"
+                     Replies="threadReplies"
+                     OnClose="CloseThread"
+                     OnReplySend="SendThreadReply" />
+    }
+</div>
+
+@code {
+    private List<Services.Channel> channels = [];
+    private List<Services.Message> messages = [];
+    private List<Services.ThreadSummary> threadSummaries = [];
+    private List<Services.Message> threadReplies = [];
+    private Services.Message? threadRootMessage;
+
+    private int selectedChannelId;
+    private string currentChannelName = "";
+    private string currentChannelDescription = "";
+    private bool threadOpen;
+    private bool isLoadingMore;
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        selectedChannelId = channelId;
+        var channel = channels.First(c => c.Id == channelId);
+        currentChannelName = channel.Name;
+        currentChannelDescription = channel.Description;
+
+        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        await ChatService.MarkChannelReadAsync(channelId);
+
+        // Rebuild thread summaries from messages that have replies
+        threadSummaries = BuildThreadSummaries(messages);
+
+        CloseThreadSync();
+        StateHasChanged();
+    }
+
+    private async Task SendMessage(string content)
+    {
+        var message = await ChatService.SendMessageAsync(selectedChannelId, content, null);
+        messages.Add(message);
+    }
+
+    private async Task OpenThread(int rootMessageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
+        threadReplies = await ChatService.GetThreadAsync(rootMessageId);
+        threadOpen = true;
+    }
+
+    private void CloseThreadSync()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private Task CloseThread()
+    {
+        CloseThreadSync();
+        return Task.CompletedTask;
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (threadRootMessage is null) return;
+        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
+        threadReplies.Add(reply);
+
+        // Update thread summary count
+        var existing = threadSummaries.FirstOrDefault(t => t.RootMessageId == threadRootMessage.Id);
+        if (existing is not null)
+        {
+            threadSummaries.Remove(existing);
+        }
+        threadSummaries.Add(new Services.ThreadSummary(threadRootMessage.Id, threadReplies.Count, DateTime.UtcNow));
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        // Refresh messages to reflect the new reaction
+        messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messages.Count);
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (isLoadingMore) return;
+        isLoadingMore = true;
+        StateHasChanged();
+
+        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
+        if (older.Count > 0)
+        {
+            messages.InsertRange(0, older);
+            threadSummaries = BuildThreadSummaries(messages);
+        }
+
+        isLoadingMore = false;
+    }
+
+    private static List<Services.ThreadSummary> BuildThreadSummaries(List<Services.Message> msgs)
+    {
+        var replies = msgs.Where(m => m.ReplyToId.HasValue).ToList();
+        return replies
+            .GroupBy(m => m.ReplyToId!.Value)
+            .Select(g => new Services.ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
+            .ToList();
