+
+/* Channel Sidebar */
+.channel-sidebar {
+    width: 20%;
+    min-width: 200px;
+    background: #2c2f33;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-right: 1px solid #202225;
+}
+
+.sidebar-title {
+    padding: 16px;
+    margin: 0;
+    font-size: 1rem;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+    color: #8e9297;
+    border-bottom: 1px solid #202225;
+}
+
+.channel-list {
+    overflow-y: auto;
+    flex: 1;
+}
+
+.channel-item {
+    padding: 8px 16px;
+    cursor: pointer;
+    display: flex;
+    flex-wrap: wrap;
+    align-items: center;
+    gap: 4px;
+    transition: background 0.15s;
+}
+
+.channel-item:hover {
+    background: #36393f;
+}
+
+.channel-item.active {
+    background: #393c43;
+    border-left: 3px solid #5865f2;
+}
+
+.channel-name {
+    font-weight: 600;
+    font-size: 0.95rem;
+    flex: 1;
+}
+
+.channel-description {
+    width: 100%;
+    font-size: 0.75rem;
+    color: #8e9297;
+    white-space: nowrap;
+    overflow: hidden;
+    text-overflow: ellipsis;
+}
+
+.unread-badge {
+    background: #ed4245;
+    color: white;
+    border-radius: 10px;
+    padding: 1px 6px;
+    font-size: 0.7rem;
+    font-weight: 700;
+}
+
+/* Message Area */
+.message-area {
+    flex: 1;
+    display: flex;
+    flex-direction: column;
+    background: #36393f;
+    color: #dcddde;
+    min-width: 0;
+}
+
+.chat-layout:not(.thread-open) .message-area {
+    width: 80%;
+}
+
+.chat-layout.thread-open .message-area {
+    width: 55%;
+}
+
+.message-area-header {
+    padding: 12px 20px;
+    border-bottom: 1px solid #202225;
+    flex-shrink: 0;
+}
+
+.message-area-header h2 {
+    margin: 0;
+    font-size: 1.1rem;
+    color: #ffffff;
+}
+
+.message-area-header p {
+    margin: 4px 0 0;
+    font-size: 0.8rem;
+    color: #8e9297;
+}
+
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 16px 20px;
+}
+
+.loading-indicator {
+    text-align: center;
+    padding: 12px;
+    color: #8e9297;
+    font-size: 0.85rem;
+}
+
+/* Message Item */
+.message-item {
+    padding: 8px 12px;
+    border-radius: 4px;
+    position: relative;
+    margin-bottom: 4px;
+    transition: background 0.1s;
+}
+
+.message-item:hover {
+    background: #32353b;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 2px;
+}
+
+.message-author {
+    font-weight: 600;
+    color: #ffffff;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.7rem;
+    color: #72767d;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+    word-wrap: break-word;
+}
+
+.message-reactions {
+    display: flex;
+    gap: 4px;
+    margin-top: 6px;
+    flex-wrap: wrap;
+}
+
+.reaction-badge {
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 2px 8px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: background 0.1s;
+}
+
+.reaction-badge:hover {
+    background: #5865f2;
+    border-color: #5865f2;
+}
+
+.thread-link {
+    background: none;
+    border: none;
+    color: #5865f2;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    margin-top: 4px;
+    font-weight: 500;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+.message-actions {
+    position: absolute;
+    top: -8px;
+    right: 12px;
+    display: flex;
+    gap: 4px;
+    background: #2f3136;
+    border: 1px solid #4f545c;
+    border-radius: 4px;
+    padding: 2px;
+}
+
+.action-btn {
+    background: none;
+    border: none;
+    color: #dcddde;
+    cursor: pointer;
+    padding: 4px 8px;
+    font-size: 0.75rem;
+    border-radius: 3px;
+}
+
+.action-btn:hover {
+    background: #5865f2;
+    color: white;
+}
+
+.emoji-picker {
+    position: absolute;
+    top: -8px;
+    right: 12px;
+    transform: translateY(-100%);
