+    border-radius: 6px;
+    padding: 6px;
+    display: flex;
+    gap: 4px;
+}
+
+.emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+}
+
+.emoji-btn:hover {
+    background: #36393f;
+}
+
+/* Message Input */
+.message-input {
+    padding: 12px 20px;
+    border-top: 1px solid #202225;
+    display: flex;
+    gap: 8px;
+    align-items: flex-end;
+    flex-shrink: 0;
+}
+
+.message-input textarea {
+    flex: 1;
+    background: #40444b;
+    border: none;
+    border-radius: 6px;
+    padding: 10px 14px;
+    color: #dcddde;
+    font-size: 0.9rem;
