+    font-weight: 600;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.btn-send:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.btn-send:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2f3136;
+    color: #dcddde;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #202225;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #ffffff;
+}
+
+.btn-close-thread {
+    background: none;
+    border: none;
+    color: #8e9297;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.btn-close-thread:hover {
+    background: #36393f;
+    color: #ffffff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    background: #36393f;
+    border-bottom: 1px solid #202225;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    margin-top: 4px;
+    color: #b9bbbe;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+.thread-reply {
+    margin-bottom: 12px;
+    padding: 6px 0;
+}
+
+.thread-reply .message-content {
+    font-size: 0.85rem;
+}
